create table if not exists public.proveedores (
 id uuid primary key default gen_random_uuid(), nombre text not null, ruc text, telefono text, email text, direccion text, contacto text, notas text, activo boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create unique index if not exists proveedores_ruc_uq on public.proveedores(ruc) where ruc is not null and btrim(ruc)<>'';

create table if not exists public.ordenes_compra (
 id uuid primary key default gen_random_uuid(), numero bigint generated by default as identity unique, proveedor_id uuid not null references public.proveedores(id), location_id uuid not null references public.locations(id), estado text not null default 'borrador' check (estado in ('borrador','enviada','parcial','recibida','cancelada')), fecha_orden timestamptz not null default now(), fecha_esperada date, observacion text, creado_por uuid not null references public.staff(id), total numeric(14,2) not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.orden_compra_items (
 id uuid primary key default gen_random_uuid(), orden_id uuid not null references public.ordenes_compra(id) on delete cascade, variant_id uuid not null references public.product_variants(id), cantidad_pedida integer not null check(cantidad_pedida>0), cantidad_recibida integer not null default 0 check(cantidad_recibida>=0), costo_unitario numeric(14,2) not null check(costo_unitario>=0), subtotal numeric(14,2) generated always as (cantidad_pedida*costo_unitario) stored, unique(orden_id,variant_id), check(cantidad_recibida<=cantidad_pedida)
);
create table if not exists public.recepciones_compra (
 id uuid primary key default gen_random_uuid(), orden_id uuid not null references public.ordenes_compra(id), recibido_por uuid not null references public.staff(id), fecha timestamptz not null default now(), observacion text, created_at timestamptz not null default now()
);
create table if not exists public.recepcion_compra_items (
 id uuid primary key default gen_random_uuid(), recepcion_id uuid not null references public.recepciones_compra(id) on delete cascade, orden_item_id uuid not null references public.orden_compra_items(id), cantidad integer not null check(cantidad>0), costo_unitario numeric(14,2) not null check(costo_unitario>=0)
);

alter table public.proveedores enable row level security;
alter table public.ordenes_compra enable row level security;
alter table public.orden_compra_items enable row level security;
alter table public.recepciones_compra enable row level security;
alter table public.recepcion_compra_items enable row level security;

create policy proveedores_admin on public.proveedores for all to authenticated using(private.auth_is_admin()) with check(private.auth_is_admin());
create policy oc_admin on public.ordenes_compra for select to authenticated using(private.auth_is_admin() or location_id=private.auth_location_id());
create policy oc_write_admin on public.ordenes_compra for all to authenticated using(private.auth_is_admin()) with check(private.auth_is_admin());
create policy oci_read on public.orden_compra_items for select to authenticated using(exists(select 1 from public.ordenes_compra o where o.id=orden_id and (private.auth_is_admin() or o.location_id=private.auth_location_id())));
create policy oci_write_admin on public.orden_compra_items for all to authenticated using(private.auth_is_admin()) with check(private.auth_is_admin());
create policy rc_read on public.recepciones_compra for select to authenticated using(exists(select 1 from public.ordenes_compra o where o.id=orden_id and (private.auth_is_admin() or o.location_id=private.auth_location_id())));
create policy rci_read on public.recepcion_compra_items for select to authenticated using(exists(select 1 from public.recepciones_compra r join public.ordenes_compra o on o.id=r.orden_id where r.id=recepcion_id and (private.auth_is_admin() or o.location_id=private.auth_location_id())));

create or replace function public.crear_proveedor(p_nombre text,p_ruc text default null,p_telefono text default null,p_email text default null,p_direccion text default null,p_contacto text default null,p_notas text default null) returns public.proveedores language plpgsql security definer set search_path='public','private' as $$ declare v public.proveedores; begin if not private.auth_is_admin() then raise exception 'Solo administradores'; end if; if length(btrim(coalesce(p_nombre,'')))<2 then raise exception 'Nombre inválido'; end if; insert into public.proveedores(nombre,ruc,telefono,email,direccion,contacto,notas) values(btrim(p_nombre),nullif(btrim(p_ruc),''),nullif(btrim(p_telefono),''),nullif(btrim(p_email),''),nullif(btrim(p_direccion),''),nullif(btrim(p_contacto),''),nullif(btrim(p_notas),'')) returning * into v; return v; end $$;

create or replace function public.crear_orden_compra(p_proveedor_id uuid,p_items jsonb,p_fecha_esperada date default null,p_observacion text default null) returns public.ordenes_compra language plpgsql security definer set search_path='public','private' as $$ declare v_staff public.staff; v_orden public.ordenes_compra; x jsonb; v_total numeric:=0; begin if not private.auth_is_admin() then raise exception 'Solo administradores'; end if; select * into v_staff from public.staff where user_id=auth.uid() and activo=true limit 1; if v_staff.id is null then raise exception 'Personal inválido'; end if; if p_items is null or jsonb_array_length(p_items)=0 then raise exception 'Orden sin productos'; end if; insert into public.ordenes_compra(proveedor_id,location_id,fecha_esperada,observacion,creado_por) values(p_proveedor_id,v_staff.location_id,p_fecha_esperada,nullif(btrim(p_observacion),''),v_staff.id) returning * into v_orden; for x in select * from jsonb_array_elements(p_items) loop insert into public.orden_compra_items(orden_id,variant_id,cantidad_pedida,costo_unitario) values(v_orden.id,(x->>'variant_id')::uuid,(x->>'cantidad')::int,(x->>'costo_unitario')::numeric); v_total:=v_total+((x->>'cantidad')::numeric*(x->>'costo_unitario')::numeric); end loop; update public.ordenes_compra set total=round(v_total,2) where id=v_orden.id returning * into v_orden; return v_orden; end $$;

create or replace function public.recibir_orden_compra(p_orden_id uuid,p_items jsonb,p_observacion text default null) returns public.recepciones_compra language plpgsql security definer set search_path='public','private' as $$ declare v_staff public.staff; v_orden public.ordenes_compra; v_rec public.recepciones_compra; x jsonb; v_item public.orden_compra_items; v_qty int; v_pend int; begin select * into v_staff from public.staff where user_id=auth.uid() and activo=true limit 1; if v_staff.id is null or not (v_staff.rol='administrador' or v_staff.puesto in ('tecnico','encargado','jefa')) then raise exception 'Sin permiso para recibir compras'; end if; select * into v_orden from public.ordenes_compra where id=p_orden_id for update; if v_orden.id is null or v_orden.location_id<>v_staff.location_id then raise exception 'Orden inválida o de otra sucursal'; end if; if v_orden.estado in ('recibida','cancelada') then raise exception 'Orden no recepcionable'; end if; if p_items is null or jsonb_array_length(p_items)=0 then raise exception 'Recepción vacía'; end if; insert into public.recepciones_compra(orden_id,recibido_por,observacion) values(v_orden.id,v_staff.id,nullif(btrim(p_observacion),'')) returning * into v_rec; for x in select * from jsonb_array_elements(p_items) loop select * into v_item from public.orden_compra_items where id=(x->>'orden_item_id')::uuid and orden_id=v_orden.id for update; if v_item.id is null then raise exception 'Línea inválida'; end if; v_qty:=(x->>'cantidad')::int; if v_qty<=0 or v_item.cantidad_recibida+v_qty>v_item.cantidad_pedida then raise exception 'Cantidad excede pendiente'; end if; insert into public.recepcion_compra_items(recepcion_id,orden_item_id,cantidad,costo_unitario) values(v_rec.id,v_item.id,v_qty,v_item.costo_unitario); update public.orden_compra_items set cantidad_recibida=cantidad_recibida+v_qty where id=v_item.id; insert into public.inventory(variant_id,location_id,cantidad) values(v_item.variant_id,v_orden.location_id,v_qty) on conflict(variant_id,location_id) do update set cantidad=public.inventory.cantidad+excluded.cantidad,updated_at=now(); insert into public.inventory_movements(variant_id,location_id,cantidad_delta,motivo,staff_id) values(v_item.variant_id,v_orden.location_id,v_qty,'Recepción compra #'||v_orden.numero,v_staff.id); end loop; select count(*) into v_pend from public.orden_compra_items where orden_id=v_orden.id and cantidad_recibida<cantidad_pedida; update public.ordenes_compra set estado=case when v_pend=0 then 'recibida' else 'parcial' end,updated_at=now() where id=v_orden.id; return v_rec; end $$;

grant execute on function public.crear_proveedor(text,text,text,text,text,text,text) to authenticated;
grant execute on function public.crear_orden_compra(uuid,jsonb,date,text) to authenticated;
grant execute on function public.recibir_orden_compra(uuid,jsonb,text) to authenticated;

create trigger audit_proveedores after insert or update or delete on public.proveedores for each row execute function private.registrar_auditoria();
create trigger audit_ordenes_compra after insert or update or delete on public.ordenes_compra for each row execute function private.registrar_auditoria();
create trigger audit_recepciones_compra after insert or update or delete on public.recepciones_compra for each row execute function private.registrar_auditoria();